arguments.command:
python3 - <<'EOF'
import yaml, glob
for path in sorted(glob.glob('.github/workflows/*.yml')):
    doc = yaml.safe_load(open(path))
    jobs = doc.get('jobs') or {}
    rows = []
    for name, job in jobs.items():
        perm = job.get('permissions')
        if perm is None:
            rows.append(f"{name}:NO-JOB-PERM")
        else:
            scopes = ",".join(f"{k}={v}" for k,v in sorted(perm.items())) if isinstance(perm, dict) else str(perm)
            rows.append(f"{name}[{scopes}]")
    print(path.split('/')[-1])
    for r in rows: print("   ", r)
EOF

